head.script:
scwin.onpageload = function() {
	scwin.log = {};
	window.a = '$p.getRuntimeId("scwin", "parent") : ' + $p.id + 'popup1_wframe_scwin';
};

scwin.ibx_openPopup_onclick = function(e) {
	requires("uiplugin.popup");
	var options = {
		id: "popup1",
		type: "window",
		width: "700px",
		height: "600px",
		top: "130px",
		left: "400px",
		popupName: "openPopup1",
		modal: true,
		useIFrame: true,
		scrollbars: "true",
		resizable: "true",
		menubar: true,
		frameMode: "wframe",
		useModalStack: true,
		alwaysOnTop: false,
		useControl: true
	};
	$p.openPopup("/sample/common_link/p_popup_openPopup_WPFF-208_(WSQ-3494)_wframe1.xml", options);
};

scwin.checkLog1 = function() {
	return (scwin.log["window.log1"] == window.a);
};

scwin.checkLog2 = function() {
	return (scwin.log["window.log2"] == '$p.parent().$p.getFrameId() : ' + $p.id + 'popup1_wframe');
};

scwin.checkLog3 = function() {
	return (scwin.log["window.log3"] == '$p.parent().scwin.popupId : ' + $p.id + 'popup1');
};
